Q=[(1,True,"Prohlédněte si zobrazený e-mail. Které skutečnosti na něm ukazují, že jde pravděpodobně o&nbsp;phishing?",["Adresa odesílatele je z&nbsp;domény, kterou organizace nepoužívá.","E-mail je napsán česky.","Zpráva žádá o&nbsp;zadání hesla přes odkaz v&nbsp;e-mailu.","Zpráva nikoho neoslovuje jménem.","Zpráva vyvíjí nátlak a&nbsp;stanoví krátký časový limit.","E-mail má vyplněný předmět.","Odkaz ve skutečnosti vede na jinou doménu, než jakou používá firemní portál."]),
(2,False,"Do pracovní schránky vám přišel e-mail, který vám připadá podezřelý: nečekaná příloha a&nbsp;výzva ke kliknutí na odkaz. Jak správně postupujete?",["Přepošlu e-mail všem kolegům z&nbsp;oddělení, aby byli varováni.","Neotevírám přílohu ani odkaz a&nbsp;e-mail nahlásím podle interního postupu organizace.","E-mail trvale smažu a&nbsp;nikomu nic neříkám, tím je věc vyřízená.","Odpovím odesílateli a&nbsp;zeptám se, zda zprávu poslal opravdu on.","Přílohu otevřu jen na pracovním počítači, protože případný škodlivý kód tam stejně zachytí firemní antivir."]),
(3,False,"Po najetí myší na odkaz se zobrazí cílová adresa https://firma.example.overeni-uctu.example/log&shy;in. Kdo ve skutečnosti řídí web, na který odkaz vede?",["Nelze to určit, dokud stránku neotevřete.","Vlastník domény overeni-uctu.example.","Vlastník domény firma.example.","Společně obě domény, protože jsou v&nbsp;adrese uvedeny obě."]),
(4,True,"Klikli jste na odkaz v&nbsp;e-mailu a&nbsp;na otevřené stránce zadali své pracovní přihlašovací údaje. Teprve potom jste si všimli, že adresa nepatří vaší organizaci. Co uděláte?",["Ihned to nahlásím podle interního postupu, i&nbsp;když se zatím nic zjevného nestalo.","Počkám, zda se objeví nějaké problémy, a&nbsp;teprve pak to řeším.","Popíšu, co přesně jsem zadal a&nbsp;kdy, aby bezpečnostní tým mohl zkontrolovat účet.","Nic nedělám, protože mám zapnuté vícefaktorové ověření.","E-mail trvale smažu ze schránky i&nbsp;z&nbsp;koše, aby na něj nikdo jiný nekliknul.","Co nejdříve změním heslo přes oficiální přihlášení (ne přes odkaz ze zprávy), případně podle pokynů IT."]),
(5,True,"Pracujete na účtárně. Přijde e-mail, který vypadá jako od stálého dodavatele: oznamuje změnu bankovního účtu a&nbsp;žádá, aby splatná faktura byla uhrazena už na nový účet. Co uděláte?",["Postupuji podle schvalovacího procesu organizace pro změnu platebních údajů (např. kontrola druhou osobou).","Podezřelý požadavek nahlásím podle interního postupu.","Odpovím na e-mail a&nbsp;požádám o&nbsp;písemné potvrzení změny.","Zavolám na telefonní číslo uvedené v&nbsp;podpisu tohoto e-mailu.","Změnu ověřím telefonicky u&nbsp;dodavatele na čísle, které mám z&nbsp;dřívější smlouvy nebo evidence, ne z&nbsp;tohoto e-mailu.","Platbu odešlu, protože logo i&nbsp;formát faktury odpovídají předchozím."])]
ALT="Náhled e-mailu. Od: IT podpora, adresa helpdesk@it-podpora-overeni.example. Předmět: URGENTNÍ: Váš účet bude do 2 hodin zablokován. Text: Dobrý den, zjistili jsme neobvyklou aktivitu. Pro zachování přístupu ihned ověřte své heslo na odkazu níže. Odkaz: http://login.firma-portal.example.ru-overeni.example/prihlaseni. Podpis: IT oddělení."
def q(n,v,t,o):
    tag=' <span class="vice">Více odpovědí</span>' if v else ''
    img=f'<img src="../assets/img/otazka-phishing-email.svg" alt="{ALT}" width="720" height="300" style="width:100%;height:auto">' if n==1 else ''
    li=''.join(f'<li style="display:grid;grid-template-columns:var(--s-4) 1fr;gap:var(--s-2)"><b class="t-kod" style="letter-spacing:0">{"ABCDEFG"[i]}</b><span>{x}</span></li>' for i,x in enumerate(o))
    return f'''<section style="display:grid;grid-template-columns:var(--s-6) 1fr;gap:var(--s-2)" aria-labelledby="q{n}">
 <p class="t-cislo t-nadpis" aria-hidden="true">{n:02d}</p>
 <div class="stack-2">
  <h2 id="q{n}" class="t-text" style="font-weight:var(--w-tucne)"><span class="sr-only">Otázka {n}: </span>{t}{tag}</h2>
  {img}
  <ol class="stack-2" style="list-style:none;padding:0">{li}</ol>
 </div>
</section>'''
def hdr(first):
    h='h1' if first else 'p'
    return f'''<header class="row-between" style="align-items:flex-start;gap:var(--s-4);padding-bottom:var(--s-3);border-bottom:var(--b-akcent) solid var(--c-grafit)">
 <div class="stack-2" style="flex:1"><p class="t-stitek">Zadání · variace 1 z 2 · Ukázková organizace (demo) · Návštěvník 6013</p><{h} class="t-nadpis">{TEST}</{h}></div>
 <p class="t-kod t-titulek" style="border:var(--b-silna) solid var(--c-grafit);padding:var(--s-2) var(--s-3)"><span class="sr-only">Kód variace </span>UG98N3X6</p>
</header>'''
p1=hdr(True)+'\n<p class="row" style="gap:var(--s-4)"><b>12 otázek</b><span>Odpovědi zapisujte jen do odpovědního listu s&nbsp;kódem <b class="t-kod" style="letter-spacing:0">UG98N3X6</b>.</span></p>\n'+q(*Q[0])+q(*Q[1])+foot('Zadání · UG98N3X6','strana 1 / 4')
p2=hdr(False)+'\n'+''.join(q(*x) for x in Q[2:])+foot('Zadání · UG98N3X6','strana 2 / 4')
